mutate Request(organization_id, item_id) as item else NotFound { item_id: item_id }
require revision_matches: item.revision == expected_revision else StaleRevision { current: item.revision }
set item.revision = item.revision + 1
set item.state = "Reopen"
set item.reason = reason
return Updated { revision: item.revision } }
